function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function money(v){return Number(v||0).toLocaleString('vi-VN')+'đ';}
async function loadKetoan(){await requireRole('ketoan');const s=await api('/finance/summary').catch(()=>null);if(s){document.getElementById('financeSummary')?.replaceChildren(document.createTextNode(`Phải thu: ${money(s.total)} · Đã thu: ${money(s.collected)} · Công nợ: ${money(s.debt)} · Tỷ lệ thu: ${s.collection_rate}%`));document.getElementById('ketoanCards')?.replaceChildren();}const body=document.getElementById('feeBody');if(body){try{const rows=await api('/finance/fees');body.innerHTML=rows.length?rows.map(x=>`<tr><td>${esc(x.mssv)}</td><td>${esc(x.student)}</td><td>${esc(x.room||'-')}</td><td>${x.month}</td><td>${money(x.amount)}</td><td>${esc(x.status)}</td><td>${x.status==='Chưa thu'?`<button class="btn btn-primary" onclick="confirmPayment(${x.id})">Xác nhận</button>`:'-'}</td></tr>`).join(''):'<tr><td colspan="7">Chưa có khoản thu.</td></tr>'}catch(e){body.innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`}}const stat=document.getElementById('financeStats');if(stat){const x=await api('/finance/summary');stat.innerHTML=`<div class="grid"><div class="card"><h3>Đã thu</h3><div class="number">${money(x.collected)}</div></div><div class="card"><h3>Công nợ</h3><div class="number">${money(x.debt)}</div></div><div class="card"><h3>Tỷ lệ thu</h3><div class="number">${x.collection_rate}%</div></div></div>`}}
async function confirmPayment(id){if(!confirm('Xác nhận khoản này đã thu?'))return;try{await api(`/finance/fees/${id}/pay`,{method:'PATCH'});await loadKetoan()}catch(e){alert(e.message)}}
document.addEventListener('DOMContentLoaded',loadKetoan);
